import Foundation
import SwiftUI

/// World layout generated by art/bloom/sprites.py (bloom_world.json).
struct BloomWorld: Decodable {
    struct Island: Decodable {
        let id: Int
        let name: String
        let price: Int
        let cells: [[Int]]
        let origin: [Int]
        let spawn: [String: Int]
        let cap: Int
    }
    struct Bridge: Decodable {
        let tile: [Int]
        let vertical: Bool
        let a: Int
        let b: Int
    }
    let tile: Int
    let islands: [Island]
    let bridges: [Bridge]

    static func load() -> BloomWorld {
        guard let url = Bundle.main.url(forResource: "bloom_world", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let w = try? JSONDecoder().decode(BloomWorld.self, from: data) else {
            fatalError("bloom_world.json missing")
        }
        return w
    }
}

struct Cell: Hashable, Codable {
    var x: Int
    var y: Int
}

struct PlacedBuilding: Codable, Hashable {
    var kind: BuildKind
    var cell: Cell
}

/// One crafting queue per building kind. Items come out one by one.
struct CraftQueue: Codable {
    var recipe: String
    var left: Int
    var progress: Double   // seconds into the current item
}

struct BloomSave: Codable {
    var inv: [String: Int] = [:]
    var coins = 0
    var xp = 0
    var level = 1
    var owned: [Int] = [0]
    var buildings: [PlacedBuilding] = []
    var pick = 0
    var lucky = false
    var queues: [String: CraftQueue] = [:]
    var savedAt = Date()
}

enum BloomPanel: Equatable {
    case build
    case building(BuildKind)
    case buy(Int)
    case inventory
}

struct BloomToast: Identifiable, Equatable {
    let id = UUID()
    let title: String
    let subtitle: String
}

/// Game state and rules. The scene drives it; the HUD observes it.
@MainActor
final class BloomGame: ObservableObject {
    let world = BloomWorld.load()

    /// Not @Published: crafting progress ticks every frame, the HUD must only
    /// redraw on real changes, so `s` publishes from willSet and progress lives apart.
    private(set) var s = BloomSave() { willSet { objectWillChange.send() } }
    /// Seconds into the current item of each queue (not published).
    private(set) var progress: [String: Double] = [:]
    @Published var panel: BloomPanel?
    @Published var combo = 0           // hits in the current chain
    @Published var toast: BloomToast?
    /// What the left context button offers right now (set by the scene).
    @Published var nearby: Nearby?

    enum Nearby: Equatable {
        case building(BuildKind)
        case island(Int)
    }

    /// Scene callbacks.
    var onIslandBought: ((Int) -> Void)?
    var onBuildingPlaced: ((PlacedBuilding) -> Void)?
    var onCrafted: ((BuildKind, BItem, Bool) -> Void)?
    var placeBuilding: ((BuildKind) -> Cell?)?

    private let key = "bloom.save.v1"
    private var lastHit: TimeInterval = 0

    init() {
        let args = ProcessInfo.processInfo.arguments
        if args.contains("-bloomReset") { UserDefaults.standard.removeObject(forKey: key) }
        if let d = UserDefaults.standard.data(forKey: key), let v = try? JSONDecoder().decode(BloomSave.self, from: d) {
            s = v
            for (k, q) in v.queues { progress[k] = q.progress }
            catchUp(seconds: Date().timeIntervalSince(v.savedAt))
        }
        if args.contains("-bloomRich") {
            for i in BItem.allCases { s.inv[i.rawValue, default: 0] += 40 }
            s.coins += 1000
        }
    }

    // MARK: - inventory

    func count(_ i: BItem) -> Int { s.inv[i.rawValue] ?? 0 }
    var coins: Int { s.coins }
    var level: Int { s.level }
    var xp: Int { s.xp }
    var xpNeed: Int { BloomContent.xpToNext(s.level) }
    var pickTier: Int { s.pick }
    var pickLucky: Bool { s.lucky }
    var damage: Int { BloomContent.picks[s.pick].damage + (s.lucky ? 1 : 0) }
    var owned: Set<Int> { Set(s.owned) }
    var buildings: [PlacedBuilding] { s.buildings }

    func has(_ c: Cost, times: Int = 1) -> Bool { c.allSatisfy { count($0.0) >= $0.1 * times } }
    private func pay(_ c: Cost, times: Int = 1) { for (i, n) in c { s.inv[i.rawValue, default: 0] -= n * times } }

    func add(_ i: BItem, _ n: Int) { s.inv[i.rawValue, default: 0] += n }
    func addCoins(_ n: Int) { s.coins += n }

    /// Items to show in the hotbar, in content order.
    var hotbar: [(BItem, Int)] { BItem.allCases.compactMap { count($0) > 0 ? ($0, count($0)) : nil } }

    // MARK: - gathering

    var comboStep: Int { min(BloomContent.maxCombo, 1 + combo / BloomContent.hitsPerStep) }

    /// Registers a hit and returns the combo multiplier (x1...x5).
    func registerHit(now: TimeInterval) -> Int {
        combo = now - lastHit <= BloomContent.comboWindow ? combo + 1 : 1
        lastHit = now
        return comboStep
    }

    func tickCombo(now: TimeInterval) {
        if combo > 0 && now - lastHit > BloomContent.comboWindow { combo = 0 }
    }

    /// Rolls the drops of a destroyed gatherable. Extra items for the combo.
    func roll(_ k: GatherKind, mult: Int) -> [(BItem, Int)] {
        var out: [(BItem, Int)] = []
        for d in k.drops where Double.random(in: 0..<1) < d.chance {
            out.append((d.item, Int.random(in: d.min...d.max)))
        }
        if mult > 1, let first = out.first { out[0] = (first.0, first.1 + mult - 1) }
        return out
    }

    /// Coins that fall out of a destroyed gatherable.
    func rollCoins(_ k: GatherKind, mult: Int) -> Int {
        let chance = 0.28 + 0.06 * Double(mult - 1) + (k.isStone ? 0.1 : 0)
        return Double.random(in: 0..<1) < chance ? Int.random(in: 1...(k.isStone ? 3 : 2)) : 0
    }

    /// Returns new level if the xp made one.
    @discardableResult
    func gainXP(_ n: Int) -> Int? {
        s.xp += n
        var up: Int?
        while s.xp >= BloomContent.xpToNext(s.level) {
            s.xp -= BloomContent.xpToNext(s.level)
            s.level += 1
            up = s.level
        }
        if let l = up {
            toast = BloomToast(title: "Уровень \(l)!", subtitle: BloomContent.levelUnlockText[l] ?? "Удар сильнее, добыча богаче")
            Sfx.play(.levelUp)
        }
        return up
    }

    // MARK: - building

    func canBuild(_ b: BuildKind) -> Bool { s.level >= b.unlockLevel && has(b.cost) && !isBuilt(b) }
    func isBuilt(_ b: BuildKind) -> Bool { s.buildings.contains { $0.kind == b } }

    func build(_ b: BuildKind) {
        guard canBuild(b), let cell = placeBuilding?(b) else { Sfx.play(.error); return }
        pay(b.cost)
        let pb = PlacedBuilding(kind: b, cell: cell)
        s.buildings.append(pb)
        panel = nil
        onBuildingPlaced?(pb)
        save()
    }

    // MARK: - crafting

    func queue(for b: BuildKind) -> CraftQueue? { s.queues[b.rawValue] }

    func craft(_ b: BuildKind, _ r: Recipe, times: Int) {
        let n = max(1, min(times, maxCraft(r)))
        guard has(r.cost, times: n) else { Sfx.play(.error); return }
        if var q = s.queues[b.rawValue], q.left > 0 {
            guard q.recipe == r.id else { Sfx.play(.error); return }
            q.left += n
            s.queues[b.rawValue] = q
        } else {
            s.queues[b.rawValue] = CraftQueue(recipe: r.id, left: n, progress: 0)
            progress[b.rawValue] = 0
        }
        pay(r.cost, times: n)
        Sfx.play(.select)
    }

    func maxCraft(_ r: Recipe) -> Int {
        r.cost.map { count($0.0) / $0.1 }.min() ?? 0
    }

    /// Advances crafting. Called by the scene each frame.
    func tick(dt: Double) {
        for b in BuildKind.allCases {
            guard let q = s.queues[b.rawValue], q.left > 0,
                  let r = b.recipes.first(where: { $0.id == q.recipe }) else { continue }
            var p = (progress[b.rawValue] ?? 0) + dt
            if p >= r.seconds {
                p -= r.seconds
                var nq = q
                nq.left -= 1
                if nq.left == 0 { p = 0 }
                s.queues[b.rawValue] = nq
                add(r.output, 1)
                onCrafted?(b, r.output, false)
            }
            progress[b.rawValue] = p
        }
    }

    private func catchUp(seconds: Double) {
        guard seconds > 0 else { return }
        for b in BuildKind.allCases {
            guard var q = s.queues[b.rawValue], q.left > 0,
                  let r = b.recipes.first(where: { $0.id == q.recipe }) else { continue }
            let p = progress[b.rawValue] ?? 0
            let done = min(q.left, Int((p + seconds) / r.seconds))
            q.left -= done
            progress[b.rawValue] = q.left > 0 ? (p + seconds).truncatingRemainder(dividingBy: r.seconds) : 0
            add(r.output, done)
            s.queues[b.rawValue] = q
        }
    }

    // MARK: - anvil

    var nextPick: PickTier? { s.pick + 1 < BloomContent.picks.count ? BloomContent.picks[s.pick + 1] : nil }

    func forgePick() {
        guard let p = nextPick, has(p.cost) else { Sfx.play(.error); return }
        pay(p.cost)
        s.pick += 1
        s.lucky = Double.random(in: 0..<1) < BloomContent.luckyChance
        onCrafted?(.anvil, .iron_bar, s.lucky)
        toast = BloomToast(title: s.lucky ? "Удачная ковка!" : p.title,
                           subtitle: s.lucky ? "\(p.title) +1 к удару" : "Удар: \(damage)")
        Sfx.play(s.lucky ? .victory : .chest)
        save()
    }

    // MARK: - market

    func sell(_ i: BItem, all: Bool) {
        let n = all ? count(i) : min(count(i), 1)
        guard n > 0 else { return }
        s.inv[i.rawValue] = count(i) - n
        s.coins += n * i.price
        Sfx.playThrottled(.coin, gap: 0.05)
    }

    // MARK: - islands

    func island(_ id: Int) -> BloomWorld.Island { world.islands[id] }

    func buy(_ id: Int) {
        let isl = island(id)
        guard !owned.contains(id), s.coins >= isl.price else { Sfx.play(.error); return }
        s.coins -= isl.price
        s.owned.append(id)
        panel = nil
        nearby = nil
        onIslandBought?(id)
        toast = BloomToast(title: isl.name, subtitle: "Остров расцвёл!")
        save()
    }

    // MARK: - save

    func save() {
        var v = s
        v.savedAt = Date()
        for (k, p) in progress { v.queues[k]?.progress = p }
        if let d = try? JSONEncoder().encode(v) { UserDefaults.standard.set(d, forKey: key) }
    }
}
